#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

SAMPLE_FILE=""
RULE_STAGE_STARTED=false
WIZARD_COMPLETE=false
# Inputs are public and session-only; never offer defaults from a local .env.
ENV_FILE=/dev/null

fail() {
  warn "$1"
  exit 1
}

cleanup() {
  local status=$?
  if [[ -n "$SAMPLE_FILE" ]]; then rm -f -- "$SAMPLE_FILE"; fi
  if [[ "$WIZARD_COMPLETE" != true && "$RULE_STAGE_STARTED" == true ]]; then
    warn "[unverified] Rollback: in your chosen service, disable/delete the rule and contact channel you created during this run."
    warn "[unverified] Follow that service's documentation; this script cannot verify or undo those changes."
  fi
  if (( status != 0 )); then warn "Stopped before completion (exit $status)."; fi
}

check_preconditions() {
  [[ -f package.json ]] || fail "Run this script from the pocket-notes repository root (package.json is missing)."
  command -v node >/dev/null 2>&1 || fail "Node.js 26 or newer is required."
  node -e 'if (Number(process.versions.node.split(".")[0]) < 26) process.exit(1)' || fail "Node.js 26 or newer is required."
  node -e 'if (JSON.parse(require("node:fs").readFileSync("package.json", "utf8")).name !== "pocket-notes") process.exit(1)' || fail "Run from the repository root: package.json must have name pocket-notes."
  command -v npm >/dev/null 2>&1 || fail "npm is required."
  SAMPLE_FILE=$(mktemp) || fail "Could not create a temporary sample file."
  cat > "$SAMPLE_FILE" <<'JSONL'
{"event":"pocket_notes.save","outcome":"success","reason":null,"operation_id":"00000000-0000-4000-8000-000000000001","time":"2026-11-17T00:15:00.000Z"}
JSONL
  local status=0
  npm run alert:save -- "$SAMPLE_FILE" --now 2026-11-17T00:15:00.000Z || status=$?
  [[ "$status" == 0 ]] || fail "Healthy sample expected exit 0, got $status. Check dependencies and alert:save."
  cat > "$SAMPLE_FILE" <<'JSONL'
{"event":"pocket_notes.save","outcome":"failure","reason":"quota_exceeded","operation_id":"00000000-0000-4000-8000-000000000001","time":"2026-11-17T00:15:00.000Z"}
{"event":"pocket_notes.save","outcome":"failure","reason":"storage_unavailable","operation_id":"00000000-0000-4000-8000-000000000002","time":"2026-11-17T00:15:00.000Z"}
{"event":"pocket_notes.save","outcome":"failure","reason":"unknown","operation_id":"00000000-0000-4000-8000-000000000003","time":"2026-11-17T00:15:00.000Z"}
JSONL
  status=0
  npm run alert:save -- "$SAMPLE_FILE" --now 2026-11-17T00:15:00.000Z || status=$?
  [[ "$status" == 1 ]] || fail "Failing sample expected exit 1, got $status. Check alert:save."
  rm -f -- "$SAMPLE_FILE"
  SAMPLE_FILE=""
  say "Preconditions passed: healthy sample exit 0; failing sample exit 1."
}

run_wizard() {
TOTAL_STAGES=7
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

stage "Preconditions"
check_preconditions
say "Run this wizard only as a person after merge. No values are persisted; reruns start fresh."

stage "Sending decision"
say "Today save signals stay in the browser console. The README promises no external requests."
say "Sending signals off-device needs an owner privacy decision and a code change."
if ! confirm "Has the owner approved off-device sending and do you want to continue?"; then
  say "Stopped. Nothing changed; no external configuration or application code was changed."
  return 0
fi

stage "Choose the receiver"
say "Choose your own receiver/collection service. Enter public information only, no credentials."
ask RECEIVER_NAME "[unverified] Receiver/collection service name:" || fail "No receiver supplied."
[[ -n "$RECEIVER_NAME" ]] || fail "Receiver name cannot be empty."
ask RECEIVER_DOCS_URL "[unverified] Official documentation URL (https://...):" || fail "No documentation URL supplied."
[[ "$RECEIVER_DOCS_URL" == https://?* ]] || fail "Supply an HTTPS documentation URL."
say "[unverified] Opening the documentation URL you supplied; its contents have not been verified."
open_url "$RECEIVER_DOCS_URL"
say "Values remain in this shell session only. No .env is written; application code reads none."

stage "Forward signals [unverified]"
say "[unverified] This service-specific path has not been confirmed from official documentation."
step "[unverified] In the chosen service's docs, find how to ingest browser log lines / JSON events."
step "[unverified] Create a follow-up ticket for code to forward pocket_notes.save lines, with owner privacy approval. No forwarding code is added now."
step "[unverified] Complete that follow-up before continuing, then send a test signal using the documented ingestion path."
pause "[unverified] Press Enter when the forwarding work and test are done."
confirm "[unverified] Is the test pocket_notes.save signal visible in your service?" || fail "Signal visibility was not confirmed."

stage "Transfer the alert rule [unverified]"
RULE_STAGE_STARTED=true
say "Exact local rule: event pocket_notes.save; rolling window 15 minutes ending at now, both boundaries included; exclude future signals."
say "Count failures only for quota_exceeded | storage_unavailable | unknown."
say "Attempts = successes + those counted failures. Fire when failures >= 3 AND failures >= 10% of attempts."
say "Exclude invalid_input and corrupt_data from both counts. Empty traffic does not fire."
step "[unverified] Use your service's documentation to create the equivalent rule yourself."
confirm "[unverified] Ready to create this rule in your service?" || fail "Rule creation declined."
pause "[unverified] Create the rule, enable it, then press Enter."
confirm "[unverified] Does the equivalent rule exist and is it enabled?" || fail "Enabled rule was not confirmed."

stage "Contact channel [unverified]"
ask CONTACT_CHANNEL "[unverified] Public contact channel name (no credentials):" || fail "No channel supplied."
[[ -n "$CONTACT_CHANNEL" ]] || fail "Contact channel name cannot be empty."
step "[unverified] Following your service's docs, create/select this contact channel and attach it to the rule."
pause "[unverified] Press Enter when the channel is attached."
confirm "[unverified] Is the contact channel attached to this rule and enabled?" || fail "Contact channel was not confirmed."

stage "Drill"
step "Use an isolated test browser profile. Make storage fail on purpose, then save notes at least 3 times within 15 minutes."
note "[unverified] Browser-dependent example: DevTools > Application > Storage > simulate a custom storage quota, if supported. Verify each attempt emits a counted failure."
confirm "[unverified] Did the alert fire in your service and reach the chosen contact channel?" || fail "Alert delivery drill failed."
step "Export the drill's console JSON lines to a local JSONL file."
ask DRILL_FILE "Local path to the exported JSONL file:" || fail "No drill file supplied."
[[ -f "$DRILL_FILE" ]] || fail "The exported JSONL file does not exist."
say "Checking the 15-minute window ending now; export and run promptly after the drill."
local status=0
npm run alert:save -- "$DRILL_FILE" || status=$?
[[ "$status" == 1 ]] || fail "Drill expected alert:save exit 1, got $status."

WIZARD_COMPLETE=true
finish
say "Receiver: $RECEIVER_NAME"
say "Documentation: $RECEIVER_DOCS_URL"
say "Contact channel: $CONTACT_CHANNEL"
say "Local exported-lines check: exit 1 (firing). No .env or application code was written."
note "[unverified] Receiver configuration and delivery were confirmed by you, not automatically verified."
}

run_wizard "$@"; exit
